from anthropic import Anthropic

client = Anthropic()

def retrieve_authorized_chunks(user_oauth_token: str, query: str, top_k: int = 5) -> list[str]:
    # <i class="qref" title="Tested in the practice exam under this concept">Security architecture review</i>, <i class="qref" title="Tested in the practice exam under this concept">Layered guardrails design</i>, <i class="qref" title="Tested in the practice exam under this concept">Model selection principles</i>, <i class="qref" title="Tested in the practice exam under this concept">Workflow vs. agentic pattern selection</i>: Authenticate & resolve user roles BEFORE retrieval
    user_claims = verify_scoped_oauth_token(user_oauth_token)
    allowed_roles = user_claims["roles"]

    # Hybrid retrieval (Dense + Sparse) with mandatory pre-prompt RBAC metadata filter
    raw_chunks = vector_store.hybrid_search(
        query=query,
        filter={"access_role": {"$in": allowed_roles}},
        top_k=top_k  # <i class="qref" title="Tested in the practice exam under this concept">Prompt contradiction resolution</i>: Keep top-k tight to historical answer coverage
    )
    # <i class="qref" title="Tested in the practice exam under this concept">Testing strategy for safety & regression</i>: Trim retrieved passages to spans relevant to the user's question (Input Preparation)
    return [trim_to_relevant_span(c.text, query) for c in raw_chunks]

def query_with_cached_preamble(user_oauth_token: str, static_policy_preamble: str, user_query: str):
    authorized_spans = retrieve_authorized_chunks(user_oauth_token, user_query)

    # <i class="qref" title="Tested in the practice exam under this concept">Cost optimization targeting dominant drivers</i>, <i class="qref" title="Tested in the practice exam under this concept">Model selection process</i>, <i class="qref" title="Tested in the practice exam under this concept">Monitoring setup sequence</i>: Place static 6,000-token policy preamble in a cacheable prefix
    return client.messages.create(
        model="claude-sonnet-4-20250514",
        max_tokens=1024,
        system=[
            {
                "type": "text",
                "text": static_policy_preamble,
                "cache_control": {"type": "ephemeral"}
            },
            {
                "type": "text",
                "text": "Cite only source-supported content. Never extrapolate beyond supplied passages."
            }
        ],
        messages=[{
            "role": "user",
            "content": f"Authorized Context:\n{chr(10).join(authorized_spans)}\n\nQuestion: {user_query}"
        }]
    )
